rows=[['vocabulary|Đồ chơi kite là gì?|Diều.|Tàu hoả.;Xe tải.;Búp bê.|Kite là diều; train, truck, doll là các đồ chơi khác.', 'grammar|Một bạn gái có một máy bay đồ chơi. Câu nào đúng?|She has a plane.|She have a plane.;She has an plane.;She plane is a.|He/she đi với has; plane bắt đầu phụ âm nên dùng a.', 'grammar|Hai bạn cùng có ba xe buýt đồ chơi, chọn câu đúng.|They have three buses.|They has three buses.;They have three bus.;They three buses has.|They dùng have, bus ở số nhiều thành buses.', 'reading|Đọc: Binh has a kite. Yen has two dolls. They have a train, too. Ai có hai búp bê?|Yen.|Binh.;Cả Binh và Yen mỗi người hai búp bê.;Chưa ai có đồ chơi.|Yen has two dolls nêu rõ người và số đồ, không gán riêng đồ của Yen cho Binh.', 'vocabulary|Tên teddy bear chỉ đồ chơi nào?|Gấu bông.|Thuyền.;Xe hơi.;Diều.|Teddy bear là gấu bông, gồm hai từ; không phải bear thật cần mang đến lớp.', 'writing|Chọn câu có số nhiều đúng khi nói hai tàu thuỷ đồ chơi.|They have two ships.|They have two ship.;They has two ships.;They have a two ships.|Two ships cần s, They đi với have; không đặt a trước two.', "communication|Em giới thiệu đồ chơi của một bạn trai, không nói đồ của mình. Mẫu nào đúng?|He has a car.|I have a car.;I'm a car.;He are car.|He has nói một bạn trai có; I have nói chính người kể có, không đúng ngôi yêu cầu.", 'pronunciation|I trong kite và oy trong toy có âm khác nhau ra sao?|Kite có /aɪ/, toy có /ɔɪ/.|Cả hai đều /iː/.;Kite có /ɔɪ/, toy có /aɪ/.;Cả hai i/oy đều câm.|Kite và toy có hai nguyên âm đôi khác nhau; nghe cả từ rồi đọc vào câu.', 'reading|Đọc: They have one truck and two planes. Nhóm có bao nhiêu máy bay đồ chơi?|Hai.|Một.;Ba.;Chưa nêu số máy bay.|Two planes cho biết hai máy bay; one truck là một xe tải, không cộng vào số máy bay.', 'writing|Tên số nhiều đúng của bus trong chủ đề đồ chơi là gì?|buses|buss;busies;buseses|Bus thêm es thành buses; không thêm y hay lặp es.', 'speaking|Giới thiệu đồ chơi hai nhân vật trên thẻ, cách nào thể hiện đổi từ một sang nhiều người?|Một người dùng He/She has, hai người dùng They have.|Luôn dùng I has.;Luôn dùng They has.;Bỏ mọi từ have/has.|Dạng chủ ngữ quyết định have/has; số lượng đồ còn quyết định danh từ số ít/số nhiều.', 'communication|Bạn không có đồ chơi thật để trưng bày. Cách tham gia phù hợp là gì?|Vẽ hoặc gấp đồ chơi giấy rồi giới thiệu theo thẻ vai.|Bỏ bạn ra khỏi hoạt động.;Tự nói bạn có đồ đắt tiền.;Chỉ so giá đồ chơi của các bạn.|Nhiệm vụ luyện câu sở hữu, có thể dùng hình tự vẽ và thông tin nhân vật tưởng tượng.'], ['vocabulary|Cụm listening to music có nghĩa gì?|Đang nghe nhạc.|Đang vẽ.;Đang xem ti vi.;Đang đọc.|Listening to music là nghe nhạc, khác watching TV và reading.', "grammar|Em đang viết, chọn câu đúng diễn tả việc đang làm.|I'm writing.|I writing.;I'm write.;I writes am.|Mẫu hiện tại đang làm dùng I am/I'm cộng hoạt động có ing.", 'communication|Muốn hỏi bạn đang làm gì lúc này, em nói gì?|What are you doing?|What do your name?;What colour are doing?;How old your doing?|What are you doing hỏi hành động hiện tại, không phải tên, tuổi hay màu.', "reading|Đọc tin nhắn mới: I'm in the art room. I'm drawing a picture. Người nói đang làm gì?|Vẽ tranh.|Nghe nhạc.;Xem ti vi.;Đọc sách.|Câu thứ hai nêu hành động drawing a picture; câu đầu chỉ nơi, không đủ để tự đoán việc.", 'writing|Chọn cách viết đúng của hoạt động write khi thêm ing.|writing|writeing;writting;writeng|Write bỏ e rồi thêm ing thành writing; không giữ e hay nhân đôi t.', 'vocabulary|Watching TV và reading a book khác nhau ở hoạt động nào?|Xem ti vi và đọc sách.|Cùng là nghe nhạc.;Chơi bóng và hát.;Viết và nhảy.|Watch TV là xem ti vi, read a book là đọc sách; cần dùng cả cụm để hiểu đúng.', "grammar|Câu nào diễn đạt em đang chơi bóng rổ lúc được hỏi?|I'm playing basketball.|I play basketball every day.;I'm play basketball.;I playing basketball am.|I'm playing mô tả đang làm. I play every day nói thói quen, khác thời điểm lúc hỏi.", 'pronunciation|Âm n cuối listen khác ng cuối singing ở đâu?|/n/ dùng đầu lưỡi, /ŋ/ dùng phần sau lưỡi.|Cả hai đều cần bật /g/ cuối.;/n/ luôn dùng hai môi.;Ng luôn đọc tên hai chữ N và G.|Listen kết /n/, singing có /ŋ/ ở ng; không thêm /g/ riêng sau /ŋ/ trong mẫu này.', "reading|Đọc: I'm singing. My friend is listening to music. Người kể đang nghe nhạc phải không?|Không, người kể đang hát; người bạn nghe nhạc.|Có, vì có từ music trong đoạn.;Cả hai đang nghe nhạc.;Không ai có hoạt động.|Phân biệt I với my friend; thông tin của hai người không đổi cho nhau.", "writing|Hoàn thành: I'm listening ___ music.|to|at;on;in|Cụm từ là listen to music; giữ to sau listening.", "communication|Bạn hỏi What are you doing? nhưng em chỉ nói I'm in my room. Em cần thêm gì để trả lời đủ?|Một câu nêu hành động đang làm, như I'm reading.|Chỉ tên phòng lần nữa.;Tuổi của người thân.;Màu căn phòng.|In my room chỉ vị trí; câu hỏi What are you doing cần hoạt động.", "speaking|Hai bạn chơi diễn tả hoạt động, cách luyện nào đúng Unit18?|Một bạn làm động tác nhẹ, bạn hỏi What are you doing, người diễn đáp I'm + ing.|Chỉ gọi tên đồ chơi.;Chỉ đếm số cửa sổ.;Hỏi tuổi rồi đáp tên màu.|Tình huống nối câu hỏi với chính hành động đang diễn, rồi đổi vai để đều được nói."], ['vocabulary|Cycling là hoạt động nào trong nhóm ngoài trời?|Đạp xe.|Trượt patin.;Nhảy dây.;Thả diều.|Cycling là đạp xe; skating, skipping, flying a kite là các hoạt động khác.', "grammar|Cô ấy đang đi bộ. Câu nào dùng đúng chủ ngữ và dạng hoạt động?|She's walking.|She walking.;She're walking.;She's walk.|She's là she is, đi với walking để nói đang làm.", "communication|Muốn hỏi một bạn trai đang làm gì ở công viên, em nói gì?|What's he doing?|Where is his age?;What's her colour?;How old doing?|What's he doing là What is he doing, hỏi hành động của người nam đang nói tới.", 'reading|Đọc: My friends are in the park. Nhi is skipping. Huy is skating. Ai đang nhảy dây?|Nhi.|Huy.;Cả hai.;Chưa ai làm gì.|Skipping là nhảy dây, gắn Nhi; skating thuộc Huy.', 'writing|Dạng ing đúng của fly trong flying a kite là gì?|flying|fling;flyying;flyeing|Fly giữ y rồi thêm ing thành flying, không bỏ hoặc nhân đôi y.', 'vocabulary|Cặp nào mô tả đi bộ và chạy?|walking và running|painting và singing;skating và cycling;flying và skipping|Walking là đi bộ, running là chạy; hai từ chỉ cách di chuyển khác nhau.', "grammar|Trả lời What's she doing? khi người đó đang tô/vẽ màu, em chọn gì?|She's painting.|I'm painting.;He's painting.;She has painting.|Câu hỏi dùng she nên đáp she is; không đổi sang I hoặc he.", 'pronunciation|Pl trong play và fl trong fly khác âm đầu nào?|/p/ của play và /f/ của fly.|/b/ và /v/.;Cả hai đều /t/.;Chỉ khác tên chữ L.|/pl/ bắt đầu âm bật /p/, /fl/ bắt đầu âm môi-răng /f/; cả hai nối sang /l/.', "reading|Đọc: Huy is in the park. He's flying a kite. Huy ở đâu?|Trong công viên.|Trong bếp.;Trong thư viện.;Trên máy bay.|In the park trả lời vị trí; flying a kite là hoạt động, không có nghĩa Huy ở trên máy bay.", 'writing|Sửa He is runing cho đúng chính tả hoạt động đang diễn ra.|He is running.|He is runeing.;He are running.;He is run.|Running viết hai n; giữ he is để đúng ngữ pháp.', 'communication|Em chỉ thấy Mai cầm chiếc diều, chưa thấy bạn làm gì. Cách mô tả nào có căn cứ?|Nói điều đang thấy và hỏi thêm trước khi khẳng định Mai đang thả diều.|Khẳng định có diều là luôn đang thả diều.;Khẳng định Mai đang trượt patin.;Gán hoạt động của người khác cho Mai.|Sở hữu/cầm đồ vật không tự chứng minh hoạt động đang diễn ra; dùng tranh có hành động rõ khi luyện.', "speaking|Làm áp phích hoạt động ngoài trời, phần trình bày nào phù hợp?|Nêu nơi và hành động của hai nhân vật bằng he/she is + ing.|Chỉ liệt kê đồ dùng không có người.;Chỉ đọc tên tuổi.;Chỉ đếm số trang giấy.|Unit19 nối thông tin vị trí với việc một người khác đang làm, khác tự kể I'm của Unit18."], ['vocabulary|Peacock là loài nào trong nhóm ở sở thú?|Công.|Khỉ.;Ngựa.;Hổ.|Peacock là công; monkey, horse, tiger là các loài khác.', 'communication|Muốn hỏi bạn nhìn thấy gì ở sở thú, dùng câu nào?|What can you see at the zoo?|How old can zoo?;What colour are you age?;Where are see can?|What can you see hỏi điều nhìn thấy; at the zoo nêu địa điểm.', 'grammar|Em nhìn thấy một con voi. Câu nào đúng?|I can see an elephant.|I can sees an elephant.;I can see a elephant.;I am can see elephant.|Sau can dùng see nguyên dạng; elephant bắt đầu âm nguyên âm nên dùng an.', "reading|Đọc cảnh mới: I can see a monkey. It's climbing a tree. Con vật đang làm gì?|Leo cây.|Nhảy múa.;Đếm.;Ngủ.|Climbing a tree nêu leo cây, không chỉ tên loài monkey.", 'vocabulary|Swinging trong cảnh con khỉ chỉ hoạt động nào?|Đu đưa.|Đếm số.;Chơi cờ.;Vẽ tranh.|Swinging là đu đưa; phân biệt với climbing là leo, counting là đếm.', "grammar|Hỏi con hổ đang làm gì, chọn câu đúng.|What's the tiger doing?|What tiger do name?;What're tiger doing?;What's the tiger colour doing?|The tiger là một con, dùng What is/What's rồi doing.", 'writing|Chọn cách viết đúng tên con khỉ.|monkey|monky;monkye;munkey|Monkey có e trước y; đọc lại từng phần khi soát chữ.', 'pronunciation|Chữ a trong parrot và dancing được luyện thế nào theo giọng Anh trong bài?|Parrot thường /æ/, dancing thường /ɑː/; âm dancing có thể khác ở giọng Mỹ.|Cả hai luôn /eɪ/.;Cả hai a đều câm.;Parrot luôn /uː/.|Parrot và dancing có cách đọc a khác trong giọng Anh; giọng Mỹ thường dùng /æ/ ở dancing.', "reading|Đọc: I can see a horse and a peacock. It's a picture of a zoo. Đoạn nêu mấy loài?|Hai loài.|Một loài.;Ba loài.;Bốn loài.|Horse và peacock là hai loài được kể, zoo là địa điểm, không phải tên một con vật.", 'writing|Hoàn thành câu mô tả: The parrot is ___ trong tranh chú vẹt nói one, two.|counting|count;counts;counted|Sau is dùng counting để nói hành động đang diễn trong tranh; đây là tình huống minh hoạ, không khẳng định mọi con vẹt đều đếm được.', "communication|Bạn hỏi What can you see? Câu nào trực tiếp trả lời điều nhìn thấy?|I can see a tiger.|It's climbing.;I'm nine.;Yes, you can.|Câu đầu nêu con vật thấy được; It's climbing chỉ hoạt động khi chưa nêu rõ con gì.", "speaking|Giới thiệu tranh sở thú tưởng tượng, em nên nói rõ điều nào?|Loài nhìn thấy và hành động trong tranh, phân biệt chuyện minh hoạ với quan sát thật.|Khẳng định mọi con vật biết vẽ và đếm.;Tự thêm loài không có trong tranh.;Chỉ nói tên mình.|Bài luyện I can see và What's the animal doing; tình huống kể cần có dữ kiện rõ và giới hạn đúng ngữ cảnh."]]
meta=[('TA3_T2_U17', 'Unit 17: Our toys', 46, 51, 'Giới thiệu đồ chơi người khác có; phân biệt he/she has với they have và tên đồ chơi số nhiều.', [('car', 'xe hơi đồ chơi', 'He has a car.'), ('kite', 'diều', 'She has a kite.'), ('train', 'tàu hoả đồ chơi', 'He has two trains.'), ('plane', 'máy bay đồ chơi', 'She has a plane.'), ('truck', 'xe tải đồ chơi', 'They have trucks.'), ('bus', 'xe buýt đồ chơi', 'They have two buses.'), ('ship', 'tàu thuỷ đồ chơi', 'They have three ships.'), ('teddy bear', 'gấu bông', 'She has a teddy bear.'), ('doll', 'búp bê', 'He has two dolls.'), ('toy', 'đồ chơi', 'This is my toy.')], ['He/She has a kite. → Anh/cô ấy có một chiếc diều.', 'They have two dolls. → Họ có hai búp bê. Tên hai người nối and cũng dùng have.', 'Một đồ dùng a car/a plane; nhiều đồ: cars/planes/trains/ships, buses; gấu bông: teddy bears.'], ['i trong kite là /aɪ/, oy trong toy là /ɔɪ/, đều là nguyên âm đôi nhưng khác nhau.', 'Nghe kite/toy rồi đọc cả cụm a kite/a toy; không đọc tên chữ thay âm trong từ.'], ['Đoạn mới: Binh has a kite. Yen has two dolls. They have a train, too.', 'Ai có hai búp bê? Đáp án: Yen. Đoạn không nói riêng Binh có hai búp bê.'], ['Viết câu theo ba thẻ: He has a plane. She has a kite. They have two ships.', 'Soát have/has theo người, a/an theo âm đầu và số nhiều buses/teddy bears.'], ['Hai người rút thẻ nhân vật và đồ chơi, lần lượt giới thiệu bằng He/She has; ghép hai thẻ rồi dùng They have.', 'Bạn nghe nêu tên và số đồ để đối chiếu, đổi vai; dùng đồ tự vẽ hoặc gấp giấy.'], ['Nghe kite/toy bằng giọng máy, chỉ thẻ và đọc lại trong câu.', 'Người thân đọc He/She has hoặc They have cùng số lượng, em chọn nhóm thẻ tương ứng.'], ['Dùng she have hoặc they has.', 'Bỏ s trong two planes, viết buss thay buses; nhầm đồ của một người thành đồ của mọi người.'], 'Gấp hoặc vẽ ba món đồ chơi cho hai nhân vật, ghi đồ mỗi người rồi thuyết trình một người và nhóm; không cần đồ chơi mua sẵn.'), ('TA3_T2_U18', 'Unit 18: Playing and doing', 52, 57, 'Nói việc mình đang làm và hỏi What are you doing; phân biệt hành động hiện tại với thói quen.', [('writing', 'đang viết', "I'm writing."), ('dancing', 'đang nhảy múa', "I'm dancing."), ('singing', 'đang hát', "I'm singing."), ('reading', 'đang đọc', "I'm reading a book."), ('playing basketball', 'đang chơi bóng rổ', "I'm playing basketball."), ('drawing a picture', 'đang vẽ tranh', "I'm drawing a picture."), ('watching TV', 'đang xem ti vi', "I'm watching TV."), ('listening to music', 'đang nghe nhạc', "I'm listening to music.")], ["What are you doing? — I'm reading. → Bạn đang làm gì? — Mình đang đọc.", "I'm = I am; sau đó dùng writing/dancing/singing/... để nói đang làm.", "I'm listening to music. I'm drawing a picture. Giữ to trong listening to, a trong a picture."], ['n cuối listen là /n/, dùng đầu lưỡi; t trong listen không phát âm.', 'ng trong singing là /ŋ/, dùng phần sau lưỡi; không thêm âm /g/ riêng ở cuối singing.'], ["Tin nhắn mới: I'm in the art room. I'm drawing a picture. My friend is listening to music.", 'Người nói đang làm gì? Đáp án: vẽ tranh. Nghe nhạc là hành động của người bạn.'], ["Viết hai tin nhắn ngắn gồm nơi và việc đang làm. Mẫu: I'm in my room. I'm reading a book.", "Đổi hoạt động và kiểm writing bỏ e của write, dancing bỏ e của dance; dùng I'm trước hoạt động."], ['Đóng vai gọi điện bằng đồ chơi giấy: hỏi What are you doing, đáp hành động đang diễn nhẹ tại chỗ.', 'Đổi vai và nói thêm nơi nếu muốn; không trả lời chỉ vị trí cho câu hỏi hành động.'], ['Nghe listening to music/singing bằng giọng máy, chú ý n/ng rồi đọc lại.', "Bạn đọc hoạt động trên một thẻ, em diễn động tác nhẹ và nói I'm cho việc đó."], ["Bỏ am trong I writing hoặc dùng I'm write.", 'Bỏ to của listening to music; trả lời vị trí mà thiếu hoạt động.'], 'Tạo bốn thẻ hoạt động, mỗi lượt rút một thẻ và diễn bằng động tác nhẹ. Bạn hỏi đang làm gì, người diễn đáp và bạn ghi đúng hoạt động.'), ('TA3_T2_U19', 'Unit 19: Outdoor activities', 58, 63, "Nói hành động của người khác bằng he/she is và hỏi What's he/she doing trong bối cảnh ngoài trời.", [('playing badminton', 'đang chơi cầu lông', "She's playing badminton."), ('running', 'đang chạy', "He's running."), ('painting', 'đang vẽ bằng màu', "She's painting."), ('walking', 'đang đi bộ', "He's walking."), ('skating', 'đang trượt patin', "He's skating."), ('cycling', 'đang đạp xe', "She's cycling."), ('flying a kite', 'đang thả diều', "He's flying a kite."), ('skipping', 'đang nhảy dây', "She's skipping."), ('park', 'công viên', "He's in the park.")], ["What's he/she doing? — He's/She's running. → Anh/cô ấy đang làm gì?", "Where's Huy? — He's in the park. → Huy ở đâu? — Trong công viên.", "He's = He is; She's = She is. Phân biệt câu hỏi vị trí với câu hỏi hành động."], ['pl trong play là /pl/, fl trong fly là /fl/; âm đầu /p/ bật hai môi, /f/ môi-răng thổi khí.', 'Nối cả cụm với /l/, không thêm tiếng pờ-lờ hoặc phờ-lờ khi nói tiếng Anh.'], ['Đoạn mới: My friends are in the park. Nhi is skipping. Huy is skating. Lan is flying a kite.', 'Ai nhảy dây và ai trượt patin? Đáp án: Nhi nhảy dây, Huy trượt patin; tìm đúng tên và hoạt động.'], ["Viết ba câu cho tranh hoạt động tự vẽ, gồm một nơi và hai hành động. Mẫu: He's in the park. He's running. She's cycling.", 'Soát running có hai n, skipping có hai p, flying giữ y; skating/cycling bỏ e trước ing.'], ["Một bạn chỉ nhân vật rõ hành động trong tranh, bạn kia hỏi What's he/she doing rồi đổi vai đáp.", "Thêm câu hỏi Where's nhân vật và đáp nơi; đừng suy hoạt động chỉ từ đồ vật đang cầm."], ["Nghe play/fly và các cụm hành động bằng giọng máy; đọc lại trong câu He's/She's.", 'Bạn đọc nơi và hoạt động, em chọn thẻ nhân vật đúng theo tranh đã thống nhất.'], ['Đổi he/she sai nhân vật; bỏ is trong He running.', 'Suy đang thả diều chỉ vì đang cầm diều; nhầm nơi với hành động.'], 'Vẽ áp phích công viên với ba nhân vật có hành động rõ, viết tên từng người rồi hỏi đáp vị trí và hoạt động; chỉ diễn nhẹ tại chỗ nếu chơi trong phòng.'), ('TA3_T2_U20', 'Unit 20: At the zoo', 64, 69, 'Gọi tên con vật nhìn thấy và mô tả hành động của nó trong cảnh hoặc tranh sở thú.', [('tiger', 'hổ', 'I can see a tiger.'), ('horse', 'ngựa', 'I can see a horse.'), ('monkey', 'khỉ', 'I can see a monkey.'), ('peacock', 'công', 'I can see a peacock.'), ('elephant', 'voi', 'I can see an elephant.'), ('parrot', 'vẹt', 'I can see a parrot.'), ('dancing', 'đang nhảy múa', "In the story, it's dancing."), ('counting', 'đang đếm', "In the picture, it's counting."), ('swinging', 'đang đu đưa', 'The monkey is swinging.'), ('climbing', 'đang leo', 'The tiger is climbing.'), ('zoo', 'sở thú', "I'm at the zoo.")], ['What can you see? — I can see a monkey/an elephant. → Bạn nhìn thấy gì?', "What's the monkey doing? — It's climbing. → Con khỉ đang làm gì?", "Sau can dùng see, không thêm s; một elephant dùng an. Con vật số ít trong mẫu dùng It is/It's.", 'Một số hành động trong tranh/chuyện là cách minh hoạ; chỉ nói điều có dữ kiện, không khẳng định mọi loài đều biết đếm hoặc vẽ.'], ['a trong parrot thường /æ/; a trong dancing thường /ɑː/ theo giọng Anh, giọng Mỹ thường /æ/.', 'Nghe cả parrot/dancing, chấp nhận biến thể giọng hợp lí; không suy mọi a có cùng âm.'], ["Cảnh mới: I can see a monkey. It's climbing a tree. I can see a horse and a peacock, too.", 'Con khỉ đang làm gì? Đáp án: leo cây. Đoạn chưa nêu hành động của ngựa hoặc công.'], ["Viết đoạn ba câu cho tranh sở thú tưởng tượng: I can see a monkey. It's swinging. I can see an elephant.", "Thêm câu hỏi What's the monkey doing và câu đáp; chỉ gán hành động có trong tranh hoặc nói rõ đang kể chuyện."], ['Chỉ tranh con vật, hỏi What can you see rồi hỏi hành động của nó; người đáp nêu tên trước, hành động sau.', 'Luyện bằng tranh tự vẽ, không cần đi sở thú; nếu nói quan sát thật, chỉ kể những gì đã thấy.'], ['Nghe parrot/dancing qua giọng máy và đọc lại trong câu.', 'Nhờ bạn đọc tên và hành động con vật trên thẻ, em chọn đúng thẻ rồi đối chiếu.'], ['Dùng can sees hoặc a elephant.', 'Đáp hành động khi câu hỏi yêu cầu tên loài; coi tranh minh hoạ như sự thật về mọi con vật.'], "Làm tranh hai con vật yêu thích với hành động rõ, giới thiệu bằng I can see và It's + ing, rồi hỏi đáp cùng bạn; ghi rõ nếu đó là câu chuyện tưởng tượng.")]
for j,(ident,title,start,end,intro,vocab,patterns,pronunciation,reading,writing,speaking,listening,errors,task) in enumerate(meta):
 c=json.loads((R/'content/tieng-viet/tap-2/TV3_T2_B30.json').read_text())
 for key in ['reading','language_practice']:c.pop(key,None)
 c.update(id=ident,title=title,subject='ta',volume=(2 if '_T2_' in ident else 1),lesson_no=([17,18,19,20][j]),topic='English Global Success',objectives=['Hiểu và dùng đúng: '+intro,'Đọc, viết và thực hành nói theo tình huống mới.','Nhận biết trọng tâm phát âm và luyện nghe bằng giọng máy có ghi nhãn.'])
 c['source'].update(pdf=('03-sgk-tieng-anh-3-tap-2-global-success.pdf' if '_T2_' in ident else '03-sgk-tieng-anh-3-tap-1-global-success.pdf'),printed_pages=[start,end],pdf_pages=[start+1,end+1],review='Đã đọc trực quan đầy đủ trang nguồn PDF ảnh quét ngày14/11/2026. Biên soạn tình huống, ví dụ và câu hỏi mới; không đăng toàn văn hay sao chép hệ thống bài tập SGK; không có bản thu âm sách.')
 c['vocabulary']=[dict(word=w,meaning_vi=m,example=e) for w,m,e in vocab]
 c['patterns']=patterns;c['pronunciation']=pronunciation;c['skills']=dict(reading=reading,writing=writing,speaking=speaking,listening=listening)
 c['audio']=dict(type='speechSynthesis',label='Giọng máy tiếng Anh của thiết bị, không phải âm thanh sách. Có thể khác theo thiết bị; nếu không phát, đọc theo mẫu và nhờ người lớn hỗ trợ.')
 c['knowledge']=dict(introduction=intro,rules=patterns,steps=['Đọc từ và nghĩa, quan sát tình huống trước khi chọn cách nói.','Nghe từ bằng giọng máy nếu thiết bị hỗ trợ, đọc lại chậm theo hướng dẫn phát âm.','Làm câu hỏi, xem giải thích rồi thực hành nói và viết theo nhiệm vụ.'],common_errors=errors)
 c['practice']=[]
 for n,row in enumerate(rows[j],1):
  skill,q,a,w,e=row.split('|');opts=[a]+w.split(';');opts=opts[n%4:]+opts[:n%4]
  c['practice'].append(dict(question_id=f'{ident}_Q{n:02}',type='mcq',skill=skill,question=q,correct_answer=a,options=opts,explanation=e))
 c['examples']=[dict(question=c['practice'][k]['question'],steps=['Nhận diện yêu cầu: '+c['practice'][k]['skill'],c['practice'][k]['explanation'],'Đáp án: '+c['practice'][k]['correct_answer']]) for k in [0,4]]
 c['activities']=[dict(title='Thực hành theo cặp: '+title,materials=['Giấy','Bút','Thẻ tự làm'],steps=[task,'Đổi vai và nhờ bạn nhắc lại thông tin đã nghe.','Sửa một lỗi sau khi đọc phần giải thích trong bài.'],check=['Đúng nội dung giao tiếp hoặc chữ/số yêu cầu.','Phát âm chậm, đủ nghe; nhờ người lớn hỗ trợ chỗ chưa chắc.','Viết đúng từ, tên riêng, dấu nháy và dấu câu.'])]
 c['assessment'].pop('distribution',None);c['assessment']['session_size']=10;c['assessment']['review_advice']='Xem lại câu sai theo nhóm từ, mẫu câu, phát âm; thực hiện cả nhiệm vụ nói và viết. Điểm trắc nghiệm không thay thế nhận xét phát âm.'
 c['games'][0].update(id=ident+'_GAME',title='Kho báu tiếng Anh: '+title,question_ids=[q['question_id'] for q in c['practice']],objective='Chọn từ và lời nói phù hợp để mở kho báu.',rules=['Mỗi lượt10 câu thuộc bài, không áp phân mức Toán.','Chọn đáp án rồi đọc giải thích. Trả lời đúng tiến thêm một bước.','Kết thúc, ôn câu sai và thử lại.'])
 c['feedback']=dict(correct='Đúng rồi! Em đọc lại từ hoặc lời nói vừa chọn.',incorrect='Đọc lời giải, chú ý tình huống rồi thử dùng mẫu câu.',teacher_note='AI_CHECKED_AWAITING_TEACHER; phần nói và phát âm cần người lớn nghe và góp ý.')
 c['status']='AI_CHECKED_AWAITING_TEACHER';c['verification']['teacher_approved']=False
 p=R/f"content/tieng-anh/tap-{c['volume']}/{ident}.json";p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(c,ensure_ascii=False,indent=2)+'\n')
 lines=['# '+title,'Trạng thái: '+c['status'],'## Nguồn',str(c['source']),'## Mục tiêu',*c['objectives'],'## Kiến thức',intro,*patterns,'## Hướng dẫn',*c['knowledge']['steps'],'## Lỗi thường gặp',*errors,'## Từ vựng']
 for v in c['vocabulary']:lines.append(v['word']+' — '+v['meaning_vi']+' — '+v['example'])
 lines+=['## Phát âm',*pronunciation,c['audio']['label']]
 for skill,items in c['skills'].items():lines+=['## '+skill,*items]
 lines+=['## Ví dụ có lời giải']
 for ex in c['examples']:lines +=[ex['question'],*ex['steps']]
 lines+=['## Hoạt động',*c['activities'][0]['steps'],*c['activities'][0]['check'],'## Luyện tập và đáp án']
 for q in c['practice']:lines +=[q['question_id']+' — '+q['question'],*q['options'],'Đáp án: '+q['correct_answer'],q['explanation']]
 lines+=['## Trò chơi',c['games'][0]['title'],*c['games'][0]['rules'],'## Đánh giá',*map(str,c['assessment'].values()),'## Phản hồi',*c['feedback'].values()]
 p.with_suffix('.md').write_text('\n\n'.join(lines)+'\n')
print('Batch43: Unit17–20;48 câu mới,4 game; trực quan T2PDF47–70.')
